// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(
        address caller,
        address recipient,
        uint256 nonce,
        uint256 strike,
        uint256 premium
    ) public {
        vm.assume(caller != address(0) && uint160(caller) > 100);
        vm.assume(recipient != address(0) && recipient != caller);
        vm.assume(address(caller).code.length == 0);
        strike = bound(strike, 0, 1e18);
        premium = bound(premium, 0, 1e18);
        nonce = bound(nonce, 0, 1e18);

        // ERC1271 signer helper acts as the order maker (adversarial counterparty
        // that must be a deployed contract to pass the signature check).
        ERC1271Signer maker = new ERC1271Signer();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(this),
            strike: strike,
            premium: premium,
            duration: 1 days,
            expiration: block.timestamp + 1 weeks,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory floorAssetTokenIds = new uint256[](0);

        vm.prank(caller);
        c.fillOrder(order, "", floorAssetTokenIds);

        // caller received the long position token with id = uint256(orderHash)
        uint256 id = uint256(c.hashOrder(order));
        require(c.ownerOf(id) == caller, "setup: caller should own long position");

        vm.prank(caller);
        c.transferFrom(caller, recipient, id);

        // GENERAL RULE: after any successful transferFrom, the token's owner is the recipient.
        assertTrue(c.ownerOf(id) == recipient, "transferFrom must change ownership to recipient");
    }
}

contract ERC1271Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(
        uint256 nonce,
        uint256 strike,
        uint256 premium,
        uint256 warpTo,
        uint256 seedMaker
    ) public {
        // keep the domain wide but admissible
        vm.warp(bound(warpTo, 1_000_000, 2_000_000_000));
        strike = bound(strike, 1, type(uint128).max);
        premium = bound(premium, 0, type(uint128).max);

        // adversarial counterparty: a contract maker that signs via EIP-1271
        // (a raw fuzzed address is an EOA and cannot produce a valid signature)
        Signer maker = new Signer();
        // token environment: baseAsset must be a contract; a permissive mock ERC20
        MockToken tok = new MockToken();

        C.Order memory order;
        order.maker = address(maker);
        order.isCall = false;
        order.isLong = false;
        order.baseAsset = address(tok);
        order.strike = strike;
        order.premium = premium;
        order.duration = 1 days;
        order.expiration = block.timestamp + 1;
        order.nonce = bound(nonce, 0, type(uint256).max - 1);

        address[] memory emptyAddrs = new address[](0);
        C.ERC20Asset[] memory emptyE20 = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory emptyE721 = new C.ERC721Asset[](0);
        order.whitelist = emptyAddrs;
        order.floorTokens = emptyAddrs;
        order.erc20Assets = emptyE20;
        order.erc721Assets = emptyE721;

        uint256[] memory noFloors = new uint256[](0);

        // fill the short put: mints the position token id = uint256(hashOrder(order)) to the maker
        c.fillOrder(order, "", noFloors);

        uint256 posId = uint256(c.hashOrder(order));

        // expire the position, then the maker withdraws
        vm.warp(block.timestamp + 2 days);
        vm.prank(address(maker));
        c.withdraw(order);

        // withdrawal burned the position token by transferFrom(maker, 0xdead, id)
        assertTrue(c.ownerOf(posId) == address(0xdead));
    }
}

// minimal EIP-1271 signer used as the order maker (counterparty with code)
contract Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

// minimal permissive ERC20 environment for the base asset
contract MockToken {
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function approve(address, uint256) external pure returns (bool) { return true; }
}

