pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C("", 0, address(this));
    }

    // mock ERC20 base asset: any transferFrom succeeds
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function testFuzz_property(uint256 seed, uint256 strike, uint256 premium) public {
        uint256 key = bound(seed, 1, type(uint256).max - 1);
        strike = bound(strike, 0, type(uint128).max);
        premium = bound(premium, 0, type(uint128).max);
        address maker = vm.addr(key);
        vm.assume(maker != address(0));

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: address(this),
            strike: strike,
            premium: premium,
            duration: 1 days,
            expiration: block.timestamp + 1,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(key, orderHash);
        bytes memory sig = abi.encodePacked(r, s, v);

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        c.fillOrder(order, sig, floorAssetTokenIds);

        uint256 longPositionId = uint256(orderHash);
        vm.prank(maker);
        c.exercise(order, floorAssetTokenIds);

        // Rule: after the owner transfers a token id to a recipient, ownerOf(id) == recipient.
        // exercise() transfers the long position to 0xdead, so it must be owned by 0xdead.
        assertTrue(c.ownerOf(longPositionId) == address(0xdead));
    }
}

