        uint256 expiration,
        address recipient1,
        address recipient2
    ) public {
        duration = bound(duration, 0, 10_000 days - 1);
        expiration = bound(expiration, block.timestamp + 1, block.timestamp + 2 ** 128);
        vm.assume(recipient1 != address(0) && recipient1 != address(maker));
        vm.assume(recipient2 != address(0) && recipient2 != address(maker) && recipient2 != recipient1);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(base),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(65);
        uint256[] memory floors = new uint256[](0);
        c.fillOrder(order, sig, floors);

        uint256 longTokenId = uint256(c.hashOrder(order));

        vm.prank(address(maker));
        c.transferFrom(address(maker), recipient1, longTokenId);

        bool ok;
        try c.transferFrom(address(maker), recipient2, longTokenId) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "original owner must not be able to re-transfer a spent token");
    }
}

