pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    struct ERC20Asset {
        address token;
        uint256 tokenAmount;
    }

    struct ERC721Asset {
        address token;
        uint256 tokenId;
    }

    struct Order {
        address maker;
        bool isCall;
        bool isLong;
        address baseAsset;
        uint256 strike;
        uint256 premium;
        uint256 duration;
        uint256 expiration;
        uint256 nonce;
        address[] whitelist;
        address[] floorTokens;
        ERC20Asset[] erc20Assets;
        ERC721Asset[] erc721Assets;
    }

    function setUp() public {
        c = new C("", 0, address(this));
        vm.warp(100);
    }

    function testFuzz_property(
        uint256 pkSeed,
        address taker,
        address to,
        uint256 premium,
        uint256 strike,
        uint256 duration,
        uint256 nonce
    ) public {
        vm.assume(taker != address(0) && taker != address(c));
        vm.assume(to != address(0) && to != address(c));
        pkSeed = bound(pkSeed, 1, type(uint256).max - 1);
        uint256 pk = pkSeed;
        address maker = vm.addr(pk);
        vm.assume(maker != address(0) && maker != taker && maker != address(c));
        premium = bound(premium, 1, 1e30);
        strike = bound(strike, 0, 1e30);
        duration = bound(duration, 1, 10_000 days - 1);

        FakeERC20 token = new FakeERC20();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        ERC20Asset[] memory erc20Assets = new ERC20Asset[](0);
        ERC721Asset[] memory erc721Assets = new ERC721Asset[](0);

        Order memory order = Order({
            maker: maker,
            isCall: true,
            isLong: false,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(pk, orderHash);
        bytes memory sig = abi.encodePacked(r, s, v);

        uint256[] memory empty = new uint256[](0);

        token.mint(taker, premium);
        vm.startPrank(taker);
        token.approve(address(c), premium);
        uint256 positionId = c.fillOrder(order, sig, empty);

        // General rule: after a successful transferFrom(from, to, id), the
        // token's recorded owner must be `to` (observable via ownerOf).
        c.transferFrom(taker, to, positionId);
        vm.stopPrank();

        bool ok;
        address newOwner;
        try c.ownerOf(positionId) returns (address o) {
            ok = true;
            newOwner = o;
        } catch {
            ok = false;
        }
        assertTrue(ok && newOwner == to, "owner after transferFrom must be `to`");
    }
}

contract FakeERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amt) external {
        balanceOf[to] += amt;
    }

    function approve(address spender, uint256 amt) external returns (bool) {
        allowance[msg.sender][spender] = amt;
        return true;
    }

    function transfer(address to, uint256 amt) external returns (bool) {
        balanceOf[msg.sender] -= amt;
        balanceOf[to] += amt;
        return true;
    }

    function transferFrom(address from, address to, uint256 amt) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) allowance[from][msg.sender] = a - amt;
        balanceOf[from] -= amt;
        balanceOf[to] += amt;
        return true;
    }
}

