pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Maker maker;

    function setUp() public {
        c = new C("", 0, address(this));
        maker = new Maker();
        // maker (ERC1271 signer + base-asset token) funds the test contract and pre-approves c
        maker.transfer(address(this), 1e30);
        maker.approveSelf(address(c), type(uint256).max);
        maker.approve(address(c), type(uint256).max);
        vm.warp(1);
    }

    function testFuzz_property(
        uint256 premium,
        uint256 strike,
        uint256 duration,
        uint256 nonce,
        address spender,
        address recipient
    ) public {
        vm.assume(spender != address(0));
        vm.assume(recipient != address(0));
        premium = bound(premium, 0, 1e24);
        strike = bound(strike, 0, 1e24);
        duration = bound(duration, 1, 9_000 days);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(maker),
            isCall: false,
            isLong: true,
            baseAsset: address(maker),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1_000 days,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory sig = new bytes(65);
        uint256[] memory floorIds = new uint256[](0);

        uint256 positionId = c.fillOrder(order, sig, floorIds);
        uint256 longId = uint256(c.hashOrder(order));
        require(positionId == longId || true, "");

        // test contract owns the long position; grant an approval, then transfer it away
        c.approve(spender, longId);
        c.transferFrom(address(this), recipient, longId);

        // RULE: after a successful transferFrom, the token's approval must be cleared
        assertTrue(c.getApproved(longId) == address(0));
    }
}

contract Maker {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor() {
        balanceOf[address(this)] = 1e30;
    }

    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }

    function approve(address spender, uint256 amount) external {
        allowance[msg.sender][spender] = amount;
    }

    function approveSelf(address spender, uint256 amount) external {
        allowance[address(this)][spender] = amount;
    }

    function transfer(address to, uint256 amount) external {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) allowance[from][msg.sender] = allowed - amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

